BNode* build(uint32_t origin, uint32_t maxLen, uint32_t depth, uint64_t rhi, uint64_t rlo, const std::vector<FibPfx>& set) {
    BNode* n = alloc();
    n->origin=origin; n->depth=depth; n->rhi=rhi; n->rlo=rlo;
    if (set.size() <= 2) {
        n->type = (set.size()==1) ? 4 : 5;
        n->own = set;
        return n;
    }
    // split
    std::vector<FibPfx> locals;
    std::map<uint32_t, std::vector<FibPfx>> kids;
    for (auto& p : set) {
        if (p.len <= depth+5) locals.push_back(p);
        else { uint32_t key = fib_bits(p.hi,p.lo,depth,6); kids[key].push_back(p); }
    }
    n->own = locals;
    for (auto& kv : kids) {
        uint64_t chi=rhi, clo=rlo;
        fib_set_bits(chi,clo,depth,6,kv.first);
        BNode* c = build(origin, maxLen, depth+6, chi, clo, kv.second);
        n->edges.push_back({kv.first, c, false});
    }
    // std::map iterates in increasing key order ✓
    n->type = n->edges.size()<=2 ? 1 : (n->edges.size()<=6 ? 2 : 3);
    return n;
}
